import itertools,json
jobs='ABCDE'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
trows=[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]
t={(a,b):trows[i][j] for i,a in enumerate(jobs) for j,b in enumerate(jobs)}
def nominal(r):
 return sum(slot[a][i] for i,a in enumerate(r))+sum(t[a,b] for a,b in zip(r,r[1:]))
def incident(r,k):
 p={a:r.index(a)+1 for a in jobs}
 if k=='rain':
  return None if p['C']==5 or p['A']==1 else nominal(r)+8*(p['E']-1)
 if k=='road':
  return None if p['B']==1 or p['C']==2 else nominal(r)+5*max(0,p['D']-3)
 return None if p['D']==5 or p['B']==5 else nominal(r)+5*max(0,p['E']-2)
rs=[''.join(r) for r in itertools.permutations(jobs) if r.index('A')<r.index('D')]
results=[]
for r in rs:
 neighbors=[(r,0)]
 for i,j in itertools.combinations(range(5),2):
  a=list(r);a[i],a[j]=a[j],a[i];s=''.join(a)
  if s.index('A')<s.index('D'): neighbors.append((s,1))
 repairs={};costs={}
 for k in ['rain','road','lift']:
  options=[(incident(s,k)+x,s) for s,x in neighbors if incident(s,k) is not None]
  if not options: break
  costs[k],repairs[k]=min(options)
 if len(costs)==3: results.append((nominal(r)+max(costs.values()),r,repairs,costs))
results.sort()
best=results[0]
# Independent neighborhood check using pairwise Hamming distances, including all publications.
check=[]
for r in rs:
 vals=[]
 for k in ['rain','road','lift']:
  opts=[incident(s,k)+(s!=r) for s in rs if sum(a!=b for a,b in zip(r,s)) in (0,2) and incident(s,k) is not None]
  if not opts: break
  vals.append(min(opts))
 if len(vals)==3: check.append((nominal(r)+max(vals),r))
assert sorted(check)==sorted((a,b) for a,b,_,_ in results)
answer={'roster':best[1],'score':best[0],'repairs':best[2],'repair_costs':best[3],'feasible_count':len(results),'next_score':min(x[0] for x in results if x[0]>best[0])}
print(json.dumps(answer))
print('published_nominal',nominal(best[1]),'verified_publications',len(rs))
for k,s in best[2].items(): print(k,s,'nominal',nominal(s),'incident including exchange',best[3][k])

