import itertools,json
start='EABDC'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
jobs='ABCDE'
rows=[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]
t={(a,b):rows[i][j] for i,a in enumerate(jobs) for j,b in enumerate(jobs)}
def distance(r):
 p=[start.index(a) for a in r];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen: seen.add(j);j=p[j]
 return 5-cycles
def nominal(r): return sum(slot[a][i] for i,a in enumerate(r))+sum(t[a,b] for a,b in zip(r,r[1:]))
classes={i:[] for i in range(3)}
for p in itertools.permutations(jobs):
 r=''.join(p);d=distance(r)
 if d>2 or r.index('A')>r.index('D') or r[4]=='C' or r[0] in 'AE': continue
 cost=nominal(r)+8*r.index('E')+d+(10 if d==2 else 0)
 classes[d].append((cost,r))
# Independently build the transposition graph to confirm minimum distances.
dists={start:0};front=[start]
for depth in (1,2):
 nxt=[]
 for r in front:
  for i,j in itertools.combinations(range(5),2):
   a=list(r);a[i],a[j]=a[j],a[i];s=''.join(a)
   if s not in dists: dists[s]=depth;nxt.append(s)
 front=nxt
for r,d in dists.items(): assert distance(r)==d
best=min(x for vals in classes.values() for x in vals)
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(vals)[0] if vals else None for d,vals in classes.items()},'feasible_by_swaps':{str(d):len(vals) for d,vals in classes.items()}}))
print('best nominal',nominal(best[1]),'late penalty',8*best[1].index('E'),'distance',distance(best[1]))

